#nullable enable // autogenerated

using System;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2.Customize
{
    public class CustomizeUI : MonoBehaviour
    {
        public void SetButtons(string[] buttonNames)
        {
            customizeButtonList.updateList(buttonNames.Length, (i, go) =>
            {
                var textButton = go.GetComponent<CustomizeIndexButton>();
                if (textButton.Exists())
                {
                    textButton.SetText(buttonNames[i]);
                }
            },
            go =>
            {
                var textButton = go.GetComponent<CustomizeIndexButton>();
                if (textButton.Exists())
                {
                    textButton.OnClick += OnButtonClickCallback;
                }
            },
            go =>
            {
                var textButton = go.GetComponent<CustomizeIndexButton>();
                if (textButton.Exists())
                {
                    textButton.OnClick -= OnButtonClickCallback;
                }
            });
        }
        public void SetIndexVisible(bool visible)
        {
            indexUI.SetActive(visible);
        }
        private void Awake()
        {
            returnButton.onClick.AddListener(() => OnReturnClick?.Invoke());
        }
        private void OnButtonClickCallback(CustomizeIndexButton button)
        {
            OnButtonClick?.Invoke(customizeButtonList.indexOf(button));
        }
        public event Action? OnReturnClick;
        public event Action<int>? OnButtonClick;
        [SerializeField]
        private ElementList customizeButtonList = null!;
        [SerializeField]
        private Button returnButton = null!;
        [SerializeField]
        private GameObject indexUI = null!;

    }
}
